#include <string.h>
#include <stddef.h>

size_t RegisterJPEGImage(void) {
    static const char *jpeg_version = "6b";
    const char *description = "JPEG (Joint Photographic Experts Group)";
    const char *mimeType = "image/jpeg";

    size_t count = 0;
    const char *const *formats = (const char *const[]){
        "JPE", "JPEG", "JPG", "JPS", "PJPEG"
    };

    for (size_t i = 0; i < 5; i++) {
        void *magick_info = SetMagickInfo(formats[i]);

        if (!magick_info)
            continue;

        SetMagickDecoder(magick_info, ReadJPEGImage);
        SetMagickEncoder(magick_info, WriteJPEGImage);

        if (strcmp(jpeg_version, "6b") >= 0)
            SetMagickThreadSupport(magick_info, MagickTrue);

        SetMagickDescription(magick_info, description);
        SetMagickMimeType(magick_info, mimeType);
        SetMagickVersion(magick_info, 0x400);

        if (!RegisterMagickInfo(magick_info))
            continue;

        count++;
    }

    return count;
}
